export function solve(input) {
  const d = input;
  const clone = (v) => JSON.parse(JSON.stringify(v));
  let users = clone(d.initial);
  let past = [],
    future = [];
  const out = [];
  for (const op of d.operations) {
    if (op.op === "undo") {
      if (past.length) {
        future.push(clone(users));
        users = past.pop();
      }
    } else if (op.op === "redo") {
      if (future.length) {
        past.push(clone(users));
        users = future.pop();
      }
    } else {
      past.push(clone(users));
      future = [];
      if (op.op === "create") users.push(clone(op.user));
      else if (op.op === "delete") users = users.filter((u) => u.id !== op.id);
      else {
        const u = users.find((u) => u.id === op.id);
        Object.assign(u, op.changes);
      }
    }
    out.push(clone(users));
  }
  return out;
}

